import React, { useState, useEffect } from 'react';
import { getEmployeeDetails } from '../../service/statisticsservice';
import './EmployeeDetails.scss';

const EmployeeDetails = () => {
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await getEmployeeDetails();
                setData(response);
            } catch (error) {
                console.error("Error fetching employee details:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    if (loading) {
        return (
            <div className="employee-info-section">
                <div className="card shadow-sm">
                    <div className="card-body text-center">
                        <div className="spinner-border text-primary" role="status">
                            <span className="visually-hidden">Đang tải...</span>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="employee-info-section">
            <div className="card shadow-sm">
                <div className="card-body">
                    <h5 className="card-title">Thông Tin Nhân Viên</h5>
                    <div className="table-responsive">
                        <table className="table table-bordered table-hover">
                            <tbody>
                                <tr>
                                    <th>Mã nhân viên:</th>
                                    <td>{data?.employee_id}</td>
                                    <th>Họ và tên:</th>
                                    <td>{`${data?.first_name} ${data?.last_name}`}</td>
                                </tr>
                                <tr>
                                    <th>Giới tính:</th>
                                    <td>{data?.gender ? 'Nam' : 'Nữ'}</td>
                                    <th>Dân tộc:</th>
                                    <td>{data?.ethnicity}</td>
                                </tr>
                                <tr>
                                    <th>Phòng ban:</th>
                                    <td>{data?.department}</td>
                                    <th>Loại hình:</th>
                                    <td>{data?.employment_type === 'Full-time' ? 'Toàn thời gian' : 'Bán thời gian'}</td>
                                </tr>
                                <tr>
                                    <th>Gói phúc lợi:</th>
                                    <td>{data?.benefit_plan}</td>
                                    <th>Khấu trừ:</th>
                                    <td>{new Intl.NumberFormat('vi-VN', {
                                        style: 'currency',
                                        currency: 'VND'
                                    }).format(data?.deductable)}</td>
                                </tr>
                                <tr>
                                    <th>Đồng chi trả:</th>
                                    <td>{data?.copay_percentage}%</td>
                                    <th>Ngày nghỉ:</th>
                                    <td>{data?.vacation_days} ngày</td>
                                </tr>
                                <tr>
                                    <th>Lương hiện tại:</th>
                                    <td>{new Intl.NumberFormat('vi-VN', {
                                        style: 'currency',
                                        currency: 'VND'
                                    }).format(data?.pay_amount)}</td>
                                    <th>Đã trả năm nay:</th>
                                    <td>{new Intl.NumberFormat('vi-VN', {
                                        style: 'currency',
                                        currency: 'VND'
                                    }).format(data?.current_year_paid)}</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default EmployeeDetails;
